-- 1. entity_relationships (PK: parent_entity_id, child_entity_id, relationship_type)
-- entity_relationships.parent_entity_id: delete duplicate's row where survivor already has the equivalent row
DELETE FROM entity_relationships
WHERE parent_entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map)
AND EXISTS (
  SELECT 1 FROM entity_relationships e2
  JOIN _ma_sep_001_merge_map m ON m.duplicate_id = entity_relationships.parent_entity_id
  WHERE e2.parent_entity_id = m.survivor_id AND e2.child_entity_id = entity_relationships.child_entity_id AND e2.relationship_type = entity_relationships.relationship_type
);
-- entity_relationships.parent_entity_id: repoint remaining rows to survivor
UPDATE entity_relationships
SET parent_entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = entity_relationships.parent_entity_id)
WHERE parent_entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);
-- entity_relationships.child_entity_id: delete duplicate's row where survivor already has the equivalent row
DELETE FROM entity_relationships
WHERE child_entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map)
AND EXISTS (
  SELECT 1 FROM entity_relationships e2
  JOIN _ma_sep_001_merge_map m ON m.duplicate_id = entity_relationships.child_entity_id
  WHERE e2.child_entity_id = m.survivor_id AND e2.parent_entity_id = entity_relationships.parent_entity_id AND e2.relationship_type = entity_relationships.relationship_type
);
-- entity_relationships.child_entity_id: repoint remaining rows to survivor
UPDATE entity_relationships
SET child_entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = entity_relationships.child_entity_id)
WHERE child_entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);
-- safety net: drop any self-referencing row a repoint could have produced
DELETE FROM entity_relationships WHERE parent_entity_id = child_entity_id;

-- 2. fund_entity_link (PK: etf_symbol; entity_id not part of PK)
-- fund_entity_link.entity_id: simple repoint, entity_id not part of a uniqueness constraint
UPDATE fund_entity_link
SET entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = fund_entity_link.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);

-- 3. instrument_entity_map (PK: instrument_key; entity_id not part of PK)
-- instrument_entity_map.entity_id: simple repoint, entity_id not part of a uniqueness constraint
UPDATE instrument_entity_map
SET entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = instrument_entity_map.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);

