-- entity_exposure_monthly.entity_id: delete duplicate's row where survivor already has the equivalent row
DELETE FROM entity_exposure_monthly
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map)
AND EXISTS (
  SELECT 1 FROM entity_exposure_monthly e2
  JOIN _ma_sep_001_merge_map m ON m.duplicate_id = entity_exposure_monthly.entity_id
  WHERE e2.entity_id = m.survivor_id AND e2.report_month = entity_exposure_monthly.report_month AND e2.holder_entity_id = entity_exposure_monthly.holder_entity_id
);
-- entity_exposure_monthly.entity_id: repoint remaining rows to survivor
UPDATE entity_exposure_monthly
SET entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = entity_exposure_monthly.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);
-- holder_entity_id column: dry-run showed 0 affected rows (holders are funds, not in this merge set) — no statement needed, confirmed live before running

-- 5. fund_exposure_coverage (PK: report_month, holder_entity_id)
-- dry-run showed 0 affected rows (holders are funds, not in this merge set) — no statement needed, confirmed live before running

-- 6. entity_enrichment_queue (PK: entity_id itself)
-- entity_enrichment_queue.entity_id: delete duplicate's row where survivor already has the equivalent row
DELETE FROM entity_enrichment_queue
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map)
AND EXISTS (
  SELECT 1 FROM entity_enrichment_queue e2
  JOIN _ma_sep_001_merge_map m ON m.duplicate_id = entity_enrichment_queue.entity_id
  WHERE e2.entity_id = m.survivor_id
);
-- entity_enrichment_queue.entity_id: repoint remaining rows to survivor
UPDATE entity_enrichment_queue
SET entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = entity_enrichment_queue.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);

-- 7. entity_isin_map (PK: isin, lei; entity_id not part of PK)
-- entity_isin_map.entity_id: simple repoint, entity_id not part of a uniqueness constraint
UPDATE entity_isin_map
SET entity_id = (SELECT survivor_id FROM _ma_sep_001_merge_map WHERE duplicate_id = entity_isin_map.entity_id)
WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);

-- 8. Remove the now-fully-repointed duplicate rows from entity_master
DELETE FROM entity_master WHERE entity_id IN (SELECT duplicate_id FROM _ma_sep_001_merge_map);

-- 9. Drop the scratch mapping table
DROP TABLE _ma_sep_001_merge_map;
